142	/**
143	 * @brief REC/NAV/PAUSE 药丸的显隐（带入场小动效）。
144	 *
145	 * @details 1 s 轮询会反复进来，所以必须幂等：只有"隐藏 → 显示"这一拍才播，
146	 *          已经显示/正在入场时只确保 flag。关掉时停动画并复位，下次入场
147	 *          不会带着上次的中间态。位移/透明度都不进 flex 布局，旁边的图标不跳。
148	 */
149	static void status_pill_show(lv_obj_t * pill, bool on)
150	{
151	    if (pill == NULL) {
152	        return;
153	    }
154	
155	    if (!on) {
156	        helm_anim_stop(pill, status_pill_y_exec);
157	        helm_anim_stop(pill, status_pill_opa_exec);
158	        lv_obj_add_flag(pill, LV_OBJ_FLAG_HIDDEN);
159	        lv_obj_set_style_translate_y(pill, 0, 0);
160	        lv_obj_set_style_opa(pill, LV_OPA_COVER, 0);
161	        return;
162	    }
163	
164	    if (!lv_obj_has_flag(pill, LV_OBJ_FLAG_HIDDEN)) {
165	        return;   /* 已经显示（或正在入场）：不重播 */
166	    }
167	
168	    lv_obj_clear_flag(pill, LV_OBJ_FLAG_HIDDEN);
169	    lv_obj_set_style_translate_y(pill, 4, 0);
170	    lv_obj_set_style_opa(pill, LV_OPA_TRANSP, 0);
171	    helm_anim_run(pill, status_pill_y_exec, 4, 0, SB_PILL_ANIM_MS,
172	                  lv_anim_path_ease_out, status_pill_anim_done);
173	    helm_anim_run(pill, status_pill_opa_exec, 0, 255, SB_PILL_ANIM_MS,
174	                  lv_anim_path_ease_out, status_pill_anim_done);
175	}
