177	static void status_bar_set_tone(lv_obj_t * ico, uint8_t tone)
178	{
179	    if (ico == NULL) {
180	        return;
181	    }
182	
183	    if (tone == SB_TONE_HIDE) {
184	        status_bar_show(ico, false);
185	        return;
186	    }
187	
188	    status_bar_show(ico, true);
189	    if (tone == SB_TONE_WAIT) {
190	        helm_icon_set_color(ico, lv_color_white());
191	    } else if (tone == SB_TONE_RED) {
192	        helm_icon_set_color(ico, helm_color(HELM_COLOR_GPS_DEAD));
193	    } else if (tone == SB_TONE_YEL) {
194	        helm_icon_set_color(ico, helm_color(HELM_COLOR_YEL));
195	    } else {
196	        helm_icon_set_color(ico, helm_color(HELM_COLOR_GPS));
197	    }
198	}
