200	static void status_bar_set_gps(const bicycle_runtime_t * rt)
201	{
202	    uint8_t tone;
203	    bool alive = rt && rt->gnss_alive;
204	    bool valid = rt && rt->gnss_valid;
205	    uint8_t q = rt ? rt->gnss_fix_quality : 0;
206	    uint8_t sats = rt ? rt->gnss_satellites : 0;
207	    uint8_t h = rt ? rt->gnss_hdop_x10 : 0;
208	
209	    if (!alive) {
210	        tone = SB_TONE_RED;
211	    } else if (!valid) {
212	        tone = SB_TONE_WAIT;
213	    } else if (q <= 1 || sats < 5 || h > 20) {
214	        tone = SB_TONE_YEL;
215	    } else {
216	        tone = SB_TONE_GREEN;
217	    }
218	
219	    if ((int)tone == s_last_gps) {
220	        return;
221	    }
222	
223	    s_last_gps = (int)tone;
224	    status_bar_set_tone(s_gps, tone);
225	}
