227	static void status_bar_set_phone(void)
228	{
229	    uint8_t tone;
230	
231	    if (!myvendor_devctl_radio_get()) {
232	        tone = SB_TONE_HIDE;
233	    } else if (myvendor_sys_phone_ble_connected()) {
234	        tone = SB_TONE_GREEN;
235	    } else {
236	        tone = SB_TONE_WAIT;
237	    }
238	
239	    if (s_ble == NULL || (int)tone == s_last_phone) {
240	        return;
241	    }
242	
