247	static void status_bar_set_sensors(void)
248	{
249	    myvendor_devctl_sensor_rec_t recs[MYVENDOR_DEVCTL_SENSOR_REC_MAX];
250	    myvendor_sys_sensor_ui_t ui;
251	    size_t n = 0;
252	    size_t i;
253	    uint8_t k;
254	    bool want[MYVENDOR_SYS_SENSOR_KIND_N];
255	    bool sensor_on = myvendor_devctl_sensor_get();
256	
257	    for (k = 0; k < MYVENDOR_SYS_SENSOR_KIND_N; k++) {
258	        want[k] = false;
259	    }
260	
261	    if (sensor_on &&
262	        myvendor_devctl_sensor_recs_get(recs, MYVENDOR_DEVCTL_SENSOR_REC_MAX,
263	                                        &n) == 0) {
264	        for (i = 0; i < n; i++) {
265	            if (recs[i].autorc && recs[i].kind < MYVENDOR_SYS_SENSOR_KIND_N) {
266	                want[recs[i].kind] = true;
267	            }
268	        }
269	    }
270	
271	    myvendor_sys_sensor_ui_get(&ui);
272	
273	    for (k = 0; k < MYVENDOR_SYS_SENSOR_KIND_N; k++) {
274	        bool ready = (ui.slot[k].link == MYVENDOR_SYS_SENSOR_LINK_READY);
275	        uint8_t tone;
276	
277	        if (!sensor_on || !want[k]) {
278	            tone = SB_TONE_HIDE;
279	        } else if (ready) {
280	            tone = SB_TONE_GREEN;
281	        } else {
282	            tone = SB_TONE_WAIT;
283	        }
284	
285	        if (s_sns[k] == NULL || tone == s_last_sns[k]) {
286	            continue;
287	        }
288	
289	        s_last_sns[k] = tone;
290	        status_bar_set_tone(s_sns[k], tone);
291	    }
292	}
