344	        lv_obj_set_width(s_batt_fill, w);
345	        return;
346	    }
347	
348	    helm_anim_run(s_batt_fill, batt_fill_exec, cur, w, 200,
349	                  lv_anim_path_ease_out, NULL);
350	}
