352	static void status_bar_refresh(void)
353	{
354	    const bicycle_runtime_t * rt = bicycle_runtime_get();
355	    char buf[8];
356	    bool rec;
357	    bool nav;
358	    lv_color_t batt_c;
359	
360	    bicycle_status_bar_set_battery_pct(myvendor_sys_battery_percent());
361	
362	    {
363	        bool charging = (myvendor_sys_power_state() == MYVENDOR_SYS_PWR_CHARGING);
364	
365	        if (charging != (s_last_chg == 1)) {
366	            s_last_chg = charging ? 1 : 0;
367	            status_bar_set_batt_chrome(charging);
368	            s_last_batt = -1;
369	        }
370	    }
371	
372	    status_bar_set_gps(rt);
373	    status_bar_set_phone();
374	    status_bar_set_sensors();
375	
376	    if (s_time_lbl) {
377	        time_t now = time(NULL);
378	        int hour = -1;
379	        int min = -1;
380	
381	        if (now >= 1704067200) {
382	            if (!myvendor_devctl_tz_hms((long)now, &hour, &min)) {
383	                hour = -1;
384	                min = -1;
385	            }
386	        }
387	
388	        if (hour < 0) {
389	            myvendor_sys_gnss_t cfix;
390	            bool got = myvendor_sys_onboard_gnss_get(&cfix);
391	
392	            if (!got) {
393	                got = myvendor_sys_phone_gnss_get(&cfix);
394	            }
395	
396	            if (got && cfix.utc_sec >= 1704067200u) {
397	                time_t utc = (time_t)cfix.utc_sec;
398	                struct timeval tv;
399	
400	                tv.tv_sec = utc;
401	                tv.tv_usec = 0;
402	                (void)settimeofday(&tv, NULL);
403	                if (!myvendor_devctl_tz_hms((long)utc, &hour, &min)) {
404	                    hour = -1;
405	                    min = -1;
406	                }
407	            }
408	        }
409	
410	        if (hour < 0) {
411	            (void)bicycle_gpx_sim_get_wall_hms(&hour, &min);
412	        }
413	
414	        if (hour < 0) {
415	            hour = 0;
416	            min = 0;
417	        }
418	
419	        {
420	            const uint16_t hm = (uint16_t)(hour * 60 + min);
421	
422	            if (hm != s_last_time_hm) {
423	                lv_snprintf(buf, sizeof(buf), "%02d:%02d", hour, min);
424	                lv_label_set_text(s_time_lbl, buf);
425	                s_last_time_hm = hm;
426	            }
427	        }
428	    }
429	
430	    rec = rt && rt->recording;
431	    nav = map_page_nav_active(live_map_page_instance());
432	
433	    if (s_pill_rec && rec != s_last_rec) {
434	        s_last_rec = rec;
435	        status_pill_show(s_pill_rec, rec);
436	    }
437	
438	    if (s_pill_nav && nav != s_last_nav) {
439	        s_last_nav = nav;
440	        status_pill_show(s_pill_nav, nav);
441	    }
442	
443	    {
444	        bool paused = helm_shell_paused();
445	
446	        if (s_pill_pause && paused != s_last_pause) {
447	            s_last_pause = paused;
448	            status_pill_show(s_pill_pause, paused);
449	        }
450	    }
451	
452	
453	    if (s_batt_fill) {
454	        if (s_battery_pct >= 0) {
455	            if (s_battery_pct != s_last_batt) {
456	                lv_coord_t w = (lv_coord_t)lv_map(s_battery_pct, 0, 100, 0,
457	                                                  SB_BATT_FILL_MAX);
458	
459	                if (s_battery_pct > 0 && w < 2) {
460	                    w = 2;
461	                }
462	
463	                status_bar_set_batt_fill_width(w);
464	                if (s_battery_pct <= 15) {
465	                    batt_c = helm_color(HELM_COLOR_GPS_DEAD);
466	                } else if (s_battery_pct <= 35) {
467	                    batt_c = helm_color(HELM_COLOR_BATT_MID);
468	                } else {
469	                    batt_c = helm_color(HELM_COLOR_GPS);
470	                }
471	
472	                lv_obj_set_style_bg_color(s_batt_fill, batt_c, 0);
473	                s_last_batt = s_battery_pct;
474	            }
475	        } else if (s_last_batt != -2) {
476	            status_bar_set_batt_fill_width(0);
477	            s_last_batt = -2;
478	        }
479	    }
480	}
