482	/**
483	 * @brief 两条"告警闪烁"（用户 2026-09-27 加）。
484	 *
485	 * @details ① diag 判 **BLE 异常** ⇒ 蓝牙图标**红灯闪**（窗口 `SB_BLE_ALERT_MS`）；
486	 *          ② **星历下发中** ⇒ 卫星图标**黄灯闪**（判据在 gnss 侧：最近 3 s 真的写出过帧）。
487	 *
488	 * @note 只在本拍**盖**一次（相位由 `lv_tick_get()` 取 500 ms 一档 ⇒ 1 s 一个"透↔实"周期）：
489	 *       **亮相 = 目标色 + 不透明，暗相 = `OPA_TRANSP`（全透明）**。⚠ 刻意**不用** `status_bar_show()`
490	 *       —— 它加的是 `LV_OBJ_FLAG_HIDDEN`，而隐藏对象会被 flex 布局跳过 ⇒ 旁边的图标/时钟会跟着
491	 *       左右跳（用户 2026-09-27 明确要求："不是消失，而是透明度设置为全透明"）。透明只影响绘制。
492	 *       窗口**结束**时先把 opa 复位为 `COVER`、再作废 tone 缓存 ⇒ 下一拍正常取色恢复原样。
493	 */
494	static void status_bar_alert_blink(void)
495	{
496	    const bool on = ((lv_tick_get() / 500u) & 1u) != 0u;
497	    const bool ble_bad = myvendor_diag_ble_unhealthy_age_ms() < SB_BLE_ALERT_MS;
498	    const bool eph_on = myvendor_gnss_eph_active();
499	
500	    /*
501	     * ⚠ **轮询周期必须跟着闪**：默认 1 s 轮询 × 500 ms 相位 = **别名**（每次采样都落在同一
502	     * 相位 ⇒ 相位被冻住、一个颜色到底，用户 2026-09-27 实测"一直是白色"就是这样来的）。
503	     * 闪烁期间把轮询缩到 250 ms，窗口结束再恢复 1 s。
504	     */
505	    if ((ble_bad || eph_on) != s_alert_fast) {
506	        s_alert_fast = (ble_bad || eph_on);
507	        if (s_timer != NULL) {
508	            lv_timer_set_period(s_timer, s_alert_fast ? 250u : BICYCLE_STATUS_BAR_POLL_MS);
509	        }
510	    }
511	
512	    if (s_ble != NULL) {
513	        if (ble_bad) {
514	            if (on) {
515	                helm_icon_set_color(s_ble, helm_color(HELM_COLOR_GPS_DEAD));
516	                lv_obj_set_style_opa(s_ble, LV_OPA_COVER, 0);
517	            } else {
518	                lv_obj_set_style_opa(s_ble, LV_OPA_TRANSP, 0);
519	            }
520	        } else if (s_ble_bad_was) {
521	            lv_obj_set_style_opa(s_ble, LV_OPA_COVER, 0);
