42	const char *helm_icon_text(helm_icon_t id)
43	{
44	    uint32_t cp;
45	
46	    if (id < 0 || id >= HELM_ICON_COUNT) {
47	        id = HELM_ICON_INFO;
48	    }
49	    cp = s_meta[id].cp;
50	    /* PUA 0xE000..0xF8FF 都是 3 字节 UTF-8 */
51	    s_utf8[0] = (char)(0xE0u | (cp >> 12));
52	    s_utf8[1] = (char)(0x80u | ((cp >> 6) & 0x3Fu));
53	    s_utf8[2] = (char)(0x80u | (cp & 0x3Fu));
54	    s_utf8[3] = '\0';
55	    return s_utf8;
56	}
