545	        } else if (ble) {
546	            ble = false;
547	        } else {
548	            break;
549	        }
550	    }
551	
552	    left_end = sb_left_layout(x0, ble, hr, pwr, cad, pos);
553	    right_left = sb_right_layout(rec, nav, txt_ink_x0, rpos);
554	    (void)left_end;
555	    (void)right_left;
556	
557	    for (int i = 0; i < 5; i++) {
558	        s_ink_x[i] = pos[i];
559	        s_shown[i] = (pos[i] >= 0);
560	    }
561	    s_ink_x[SB_NAV] = rpos[1];
562	    s_shown[SB_NAV] = (rpos[1] >= 0);
563	    s_ink_x[SB_BAT] = rpos[2];
564	    s_shown[SB_BAT] = (rpos[2] >= 0);
565	    s_rec_x = rpos[0];
566	
567	    for (int k = 0; k < SB_SLOT_N; k++) {
568	        if (s_shown[k]) {
569	            sb_slot_place(k);
570	        }
571	    }
572	}
