576	static sb_tone_t sb_gps_tone(const bicycle_runtime_t * rt)
577	{
578	    bool alive = rt && rt->gnss_alive;
579	    bool valid = rt && rt->gnss_valid;
580	    uint8_t q = rt ? rt->gnss_fix_quality : 0;
581	    uint8_t sats = rt ? rt->gnss_satellites : 0;
582	    uint8_t hdop = rt ? rt->gnss_hdop_x10 : 0;
583	
584	    /* 旧：失联红 / 未定位白 / 弱黄闪 / 正常绿。新：红 / 浅灰 / 红 / 墨色。 */
585	    if (!alive) {
586	        return SB_TONE_RED;
587	    }
588	    if (!valid) {
589	        return SB_TONE_TRACK;
590	    }
591	    if (q <= 1 || sats < 5 || hdop > 20) {
592	        return SB_TONE_RED;
593	    }
594	    return SB_TONE_INK;
595	}
