665	static void sb_time_update(void)
666	{
667	    time_t now = time(NULL);
668	    int hour = -1;
669	    int min = -1;
670	
671	    if (now >= 1704067200) {
672	        if (!myvendor_devctl_tz_hms((long)now, &hour, &min)) {
673	            hour = -1;
674	            min = -1;
675	        }
676	    }
677	
678	    if (hour < 0) {
679	        myvendor_sys_gnss_t cfix;
680	        bool got = myvendor_sys_onboard_gnss_get(&cfix);
681	
682	        if (!got) {
683	            got = myvendor_sys_phone_gnss_get(&cfix);
684	        }
685	
686	        if (got && cfix.utc_sec >= 1704067200u) {
687	            time_t utc = (time_t)cfix.utc_sec;
688	            struct timeval tv;
689	
690	            tv.tv_sec = utc;
691	            tv.tv_usec = 0;
692	            (void)settimeofday(&tv, NULL);
693	            if (!myvendor_devctl_tz_hms((long)utc, &hour, &min)) {
694	                hour = -1;
695	                min = -1;
696	            }
697	        }
698	    }
699	
700	    if (hour < 0) {
701	        (void)bicycle_gpx_sim_get_wall_hms(&hour, &min);
702	    }
703	
704	    if (hour < 0) {
705	        hour = 0;
706	        min = 0;
707	    }
708	
709	    {
710	        const uint16_t hm = (uint16_t)(hour * 60 + min);
711	
712	        if (hm != s_last_time_hm) {
713	            sb_text_metrics_t m;
714	
715	            lv_snprintf(s_time_buf, sizeof(s_time_buf), "%02d:%02d", hour, min);
716	            lv_label_set_text(s_time, s_time_buf);
717	            sb_text_measure(s_time_buf, &m);
718	            /* 首字有 side bearing 时把 label 反向外移 ⇒ 墨迹恒定从 x=12 起。 */
719	            lv_obj_set_x(s_time, SB_TIME_X - m.ink_x0);
720	            s_time_ink_w = m.ink_w;
721	            s_last_time_hm = hm;
722	        }
723	    }
724	}
