758	    sb_tone_t tone[SB_SLOT_N];
759	    bool dot_on[SB_SLOT_N];

755	static void status_bar_refresh(void)
756	{
757	    const bicycle_runtime_t * rt = bicycle_runtime_get();
758	    sb_tone_t tone[SB_SLOT_N];
759	    bool dot_on[SB_SLOT_N];
760	    bool ble;
761	    bool rec, nav, paused;
762	    int time_w;
763	    int batt_w;
764	
765	    if (s_time == NULL) {
766	        return;
767	    }
768	
769	    bicycle_status_bar_set_battery_pct(myvendor_sys_battery_percent());
770	
771	    sb_palette_apply(false);
772	    sb_time_update();
773	    sb_battery_update();
774	
775	    for (int k = 0; k < SB_SLOT_N; k++) {
776	        tone[k] = SB_TONE_HIDE;
777	        dot_on[k] = false;
778	    }
779	
780	    /* 左簇：GPS 恒在；BLE 关电台才隐藏；心率/功率/踏频看配对。 */
781	    tone[SB_GPS] = sb_gps_tone(rt);
782	    dot_on[SB_GPS] = rt && rt->gnss_valid;
783	
784	    ble = myvendor_devctl_radio_get();
785	    tone[SB_BLE] = sb_ble_tone(ble, myvendor_sys_phone_ble_connected());
786	    dot_on[SB_BLE] = myvendor_sys_phone_ble_connected();
787	
788	    sb_sensor_tones(tone);
789	
790	    /* REC：记录中红、暂停灰；未记录隐藏（旧 PAUSE 药丸并入 REC 颜色）。 */
791	    rec = rt && rt->recording;
792	    paused = helm_shell_paused();
793	
794	    /* NAV：导航中蓝，未导航隐藏。 */
795	    nav = map_page_nav_active(live_map_page_instance());
796	    tone[SB_NAV] = nav ? SB_TONE_BLUE : SB_TONE_HIDE;
797	
798	    /* 电量：<20% 红；未知 = 浅灰；图标字形按 20/60 分级。 */
799	    if (s_battery_pct < 0) {
800	        tone[SB_BAT] = SB_TONE_TRACK;
801	    } else if (s_battery_pct < 20) {
802	        tone[SB_BAT] = SB_TONE_RED;
803	    } else {
804	        tone[SB_BAT] = SB_TONE_INK;
805	    }
806	    dot_on[SB_BAT] = true;
807	
808	    /* 布局：先把本拍数据层的可见性取出来算两簇，再统一上色。 */
809	    time_w = s_time_ink_w;
810	    batt_w = s_batt_ink_w;
811	
812	    sb_layout(time_w, batt_w,
813	              tone[SB_BLE] != SB_TONE_HIDE,
814	              tone[SB_HR] != SB_TONE_HIDE,
815	              tone[SB_PWR] != SB_TONE_HIDE,
816	              tone[SB_CAD] != SB_TONE_HIDE,
817	              rec, nav);
818	
819	    for (int k = 0; k < SB_SLOT_N; k++) {
820	        sb_slot_apply(k, tone[k], s_shown[k], dot_on[k]);
821	    }
822	
823	    /* 电量文字颜色跟图标同一支（<20% 红）。 */
824	    if (s_batt_tone_last != (uint8_t)tone[SB_BAT]) {
825	        lv_obj_set_style_text_color(s_batt, sb_tone_color(tone[SB_BAT]), 0);
826	        s_batt_tone_last = (uint8_t)tone[SB_BAT];
827	    }
828	
829	    sb_rec_apply(rec, paused);
830	}
